#!/usr/bin/env python3
"""Export the authored GenAI lessons as a readable standalone handbook."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[2];lessons=json.loads((R/'lib/genai/lessons.json').read_text())
out=['# Sukoaa GenAI engineering preparation','40 concepts, ten modules, original exercises and interview answers. Study material cannot guarantee a hiring outcome.','## How to study','Begin with the everyday explanation. Work the example and attempt the task before reading its solution. Explain the mechanism, its assumptions and a failure case aloud, then use the interview answer to identify gaps. Use the integrated course for the guided diagrams, local progress, experiments, coding tasks and mock rounds.','## Concepts']
out += [str(l['order'])+'. '+l['title'] for l in lessons]
for l in lessons:
 out += ['## '+str(l['order'])+'. '+l['title'],'Module: '+l['group'],'### Mechanism',l['simple'],'### Everyday explanation',l['analogy'],'### Engineering detail',*l['engineering'],'### Worked example',l['example'],'### Walkthrough',*['**'+s['title']+':** '+s['detail'] for s in l['stages']],'### Common misconception',l['misconception'],'### Try it',l['exercise']['prompt'],'### Worked solution',l['exercise']['solution'],'### Interview question',l['interview']['question'],l['interview']['answer'],'### Follow-up',l['interview']['followUp'],l['interview']['followUpAnswer'],'### Primary background reference',*['- ['+r['title']+']('+r['url']+')' for r in l['references']]]
out += ['## Practice and project review','The integrated course includes five mock-round formats: foundation screen, numbers, system design, coding/debugging and project ownership. These are teaching formats, not a universal employer process.','Build a cited RAG app, a calibrated eval harness, a bounded tool-using assistant or a serving/adaptation report. Retain reproducible tests, a failure analysis, explicit assumptions and evidence of your own contribution.','## Technical boundaries','Toy experiments are deterministic examples, not a hidden model or a security certification. Cost figures use editable assumed prices. Memory calculations separate weights, KV state and overhead and do not guarantee GPU fit. Agent reliability arithmetic assumes independent steps. Local course progress requires a backup before browser data is cleared.']
target=R/'public/learn/gen-ai/course-guide.md';target.parent.mkdir(parents=True,exist_ok=True);target.write_text('\n\n'.join(out)+'\n');print(target)
